solution.js:
const rawLabel = "   coffee with Sam ";
const cents = 450;
const category = "FOOD";

const trimmed = rawLabel.trim();
const label = trimmed[0].toUpperCase() + trimmed.slice(1);
const price = (cents / 100).toFixed(2);

const line = `${label}: $${price} (${category.toLowerCase()})`;
console.log(line);
